<?php $paper=['letter'=>'Letter','a4'=>'A4','legal'=>'Legal'][$printSettings['paper_size']??'letter']??'Letter';$orientation=in_array(($printSettings['orientation']??'portrait'),['portrait','landscape'],true)?$printSettings['orientation']:'portrait';$showFilters=($printSettings['include_filter_summary']??'1')==='1';$showTimestamp=($printSettings['show_timestamp']??'1')==='1';$showRanking=($printSettings['include_team_ranking']??'1')==='1'&&$type!=='standings'&&!empty($teamRanking); ?>
<!doctype html><html><head><meta charset="utf-8"><title><?= esc($event['name']??$title) ?> — <?= esc($reportLabel) ?></title><style>@page{size:<?= esc($paper) ?> <?= esc($orientation) ?>;margin:14mm}*{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#20262f;background:#fff;margin:28px}header{display:flex;align-items:center;gap:14px;border-bottom:2px solid #0c7e43;padding-bottom:14px;margin-bottom:18px}header img{width:58px;height:58px;border-radius:50%;object-fit:contain;background:#fff;padding:2px}h1{margin:0;font-size:22px;color:#172033}p{margin:4px 0;color:#667085}.subtitle{font-weight:700;color:#0c7e43}.filters{margin:0 0 16px;padding:9px 11px;border:1px solid #dce5df;background:#f7fbf8;font-size:11px;color:#536071}.print-button{margin:0 0 14px;padding:8px 12px;border:1px solid #0c7e43;border-radius:6px;background:#0c7e43;color:#fff;font-weight:700}table{width:100%;border-collapse:collapse;font-size:11px}th,td{padding:7px 8px;border:1px solid #cfd8d3;text-align:left;vertical-align:top}th{background:#eaf6ef;color:#17452e}.number{text-align:right;font-variant-numeric:tabular-nums}.ranking-title{margin:22px 0 8px;font-size:15px;color:#0c7e43}@media print{body{margin:0}.print-button{display:none}}</style></head><body><header><img src="<?= base_url('assets/img/logo.webp') ?>" alt=""><div><h1><?= esc($event['name']??$title) ?></h1><p class="subtitle"><?= esc($reportLabel) ?></p><?php if($showTimestamp): ?><p>Generated <?= esc(date('F j, Y g:i A')) ?></p><?php endif; ?></div></header><?php if($showFilters): ?><div class="filters"><?= esc($filterSummary) ?></div><?php endif; ?><button class="print-button" onclick="window.print()">Print</button><table><?php if($columns): ?><thead><tr><?php foreach($columns as $col): ?><th class="<?= in_array($col,$numericCols,true)?'number':'' ?>"><?= esc($columnLabels[$col]??$col) ?></th><?php endforeach; ?></tr></thead><?php endif; ?><tbody><?php foreach($rows as $row): ?><tr><?php foreach($columns as $col): ?><?php $value=$row[$col]??null;$display=in_array($col,$pointCols,true)&&$value!==null&&$value!==''?format_points($value):($value===null||$value===''?'—':(string)$value); ?><td class="<?= in_array($col,$numericCols,true)?'number':'' ?>"><?= esc($display) ?></td><?php endforeach; ?></tr><?php endforeach; ?><?php if(empty($rows)): ?><tr><td colspan="<?= max(1,count($columns)) ?>">No report data.</td></tr><?php endif; ?></tbody></table><?php if($showRanking): ?><h2 class="ranking-title">Official Team Ranking</h2><table><thead><tr><th class="number">Rank</th><th>Team</th><th class="number">1st</th><th class="number">2nd</th><th class="number">3rd</th><th class="number">Points</th></tr></thead><tbody><?php foreach($teamRanking as $i=>$team): ?><tr><td class="number"><?= $i+1 ?></td><td><?= esc($team['name']) ?></td><td class="number"><?= (int)$team['firsts'] ?></td><td class="number"><?= (int)$team['seconds'] ?></td><td class="number"><?= (int)$team['thirds'] ?></td><td class="number"><?= esc(format_points($team['total_points'])) ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></body></html>
